    const int spatial_tile = combined_tile / tiles_c;

    const int tile_y = spatial_tile / tiles_w;
    const int tile_x = spatial_tile % tiles_w;

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(N, Cin, Hin, Win),
        make_stride(Cin * Hin * Win, Hin * Win, Win, 1));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(Cin, CoutPerGroup, Kh, Kw),
        make_stride(CoutPerGroup * Kh * Kw, Kh * Kw, Kw, 1));

    auto gY = make_tensor(
        make_gmem_ptr(output),
        make_shape(N, Cout, Hout, Wout),
        make_stride(Cout * Hout * Wout, Hout * Wout, Wout, 1));

    auto sW = make_tensor(
        make_smem_ptr(shared_weight),
        make_shape(OutputChannelsPerBlock, CinPerGroup, Kh, Kw),
        make_stride(CinPerGroup * Kh * Kw, Kh * Kw, Kw, 1));

